    # 且所有参数校验都在读取文件之前完成。
    levels = []
    for raw_level in args.level:
        level = normalize_level(raw_level)
        if level not in SUPPORTED_LEVELS:
            return (
                f"参数错误：--level 必须是以下级别之一："
                f"{', '.join(SUPPORTED_LEVELS)}"
            )
        levels.append(level)
    params["levels"] = levels
    return None


